126	// TestGitRemote_OptionShapedURLNeverExecutes is the regression test for
127	// argument injection into the git CLI. Repo URLs arrive from index.json
128	// entries and from other plugins' entire-plugin.yml requirements, so they are
129	// attacker-influenced. git parses an option-shaped positional as an option;
130	// `--upload-pack=<cmd>` is shell-interpreted and, with no positional
131	// repository left, runs against the *ambient* repo's origin. This asserts the
132	// stronger property — not just that the call fails, but that the payload
133	// never ran.
134	//
135	// No t.Parallel: t.Chdir mutates process-global state.
136	func TestGitRemote_OptionShapedURLNeverExecutes(t *testing.T) {
137		remote := t.TempDir()
138		if out, err := exec.CommandContext(t.Context(), "git", "init", "-q", "--bare", remote).CombinedOutput(); err != nil {
139			t.Fatalf("git init --bare: %v: %s", err, out)
140		}
141		work := t.TempDir()
142		testutil.InitRepo(t, work)
143		testutil.WriteFile(t, work, "f.txt", "x")
144		testutil.GitAdd(t, work, "f.txt")
145		testutil.GitCommit(t, work, "init")
146		if out, err := exec.CommandContext(t.Context(), "git", "-C", work, "remote", "add", "origin", remote).CombinedOutput(); err != nil {
147			t.Fatalf("git remote add origin: %v: %s", err, out)
148		}
149		t.Chdir(work)
150	
151		markerDir := t.TempDir()
152		for _, tc := range []struct {
153			name   string
154			marker string
155		}{
156			{name: "ls-remote", marker: filepath.Join(markerDir, "tags-pwned")},
157			{name: "clone", marker: filepath.Join(markerDir, "meta-pwned")},
158		} {
159			payload := "--upload-pack=touch " + tc.marker + "; git-upload-pack"
160			var err error
161			if tc.name == "ls-remote" {
162				_, err = listRemoteSemverTags(context.Background(), payload)
163			} else {
164				_, err = fetchPluginMetadataAtTag(context.Background(), payload, "v1.0.0")
165			}
166			if err == nil {
167				t.Errorf("%s accepted an option-shaped repo URL", tc.name)
168			}
169			if _, statErr := os.Stat(tc.marker); statErr == nil {
170				t.Fatalf("%s: injected payload executed — %s was created", tc.name, tc.marker)
171			}
172		}
173	}
