func TestClassifyInstallArg(t *testing.T) {
	t.Parallel()
	for arg, want := range map[string]installArgKind{
		"https://github.com/entireio/entire-run": installFromURL,
		"git@github.com:entireio/entire-run.git": installFromURL,
